{
  "findings": [
    {
      "check_id": "CKV_AWS_277",
      "title": "Security group allows unrestricted public ingress",
      "resource": "aws_security_group.lb",
      "severity": "HIGH",
      "explanation": "The ingress rule allows every protocol and port from 0.0.0.0/0, exposing any attached load balancer interfaces to unsolicited traffic from the entire internet."
    },
    {
      "check_id": "CKV_AWS_382",
      "title": "Security group allows unrestricted egress",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The egress rule permits all protocols and ports to 0.0.0.0/0, allowing unrestricted outbound communication if an attached resource is compromised."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"lb\" {\n  name   = \"allow-all-lb\"\n  vpc_id = data.aws_vpc.main.id\n}\n",
  "fix_summary": "Removed the unrestricted ingress and egress rules. The security group is now deny-by-default until explicitly scoped rules are added for required ports and destinations."
}
